(6594409, 982870, 49018, '<td valign="top">Suggestive. It is somewhat a pity that the grain, which certainly makes for the image, feels so digital, at least to my eyes.</td>', 'Suggestive. It is somewhat a pity that the grain, which certainly makes for the image, feels so digital, at least to my eyes.', '2011-11-14 07:04:46.000000', NULL, 1),
(6594414, 983823, 49018, '<td valign="top">I like this a lot, the degrading DOF, the grain which definetely works and the general hue. I wonder if the tonality is due to post-processing or to lighting and subjects only. In any case, a very pleasant image (non voter)</td>', 'I like this a lot, the degrading DOF, the grain which definetely works and the general hue. I wonder if the tonality is due to post-processing or to lighting and subjects only. In any case, a very pleasant image (non voter)', '2011-11-14 07:09:24.000000', NULL, 1),
