(6595617, 983714, 61396, '<td valign="top">The tilt draws the viewer to participate in the social dynamic drawn in the image. The grain adds to the old feel. The title spells a paradox.</td>', 'The tilt draws the viewer to participate in the social dynamic drawn in the image. The grain adds to the old feel. The title spells a paradox.', '2011-11-15 16:31:25.000000', NULL, 1),
(6595626, 982870, 61396, '<td valign="top">The topography of the man face fights with the face texture for my attention, and they both win. Though I can see no dog, I think I can hear a distant bark.</td>', 'The topography of the man face fights with the face texture for my attention, and they both win. Though I can see no dog, I think I can hear a distant bark.', '2011-11-15 16:44:09.000000', NULL, 1),
(6595629, 983558, 61396, '<td valign="top">while the men are here in body only, and the woman is walking away, the kid is left alone to enjoy the scene. Great composition and contrast too.</td>', 'while the men are here in body only, and the woman is walking away, the kid is left alone to enjoy the scene. Great composition and contrast too.', '2011-11-15 16:50:15.000000', NULL, 1),
