(6596351, 983822, 114225, '<td valign="top">This is fantastic. So much emotion and story.</td>', 'This is fantastic. So much emotion and story.', '2011-11-16 10:38:49.000000', NULL, 1),
(6596352, 983281, 114225, '<td valign="top">Lovely scene, and very well processed. You really did a great job highlighting what you want the viewer to look at first.</td>', 'Lovely scene, and very well processed. You really did a great job highlighting what you want the viewer to look at first.', '2011-11-16 10:39:11.000000', NULL, 1),
