(6599288, 983722, 104230, '<td valign="top">I love the graphical design quality to this.  Great idea, and great eye to see it.  The grain helps provide a lovely neutral background against which the splash of color and leaf designs can shine.</td>', 'I love the graphical design quality to this.  Great idea, and great eye to see it.  The grain helps provide a lovely neutral background against which the splash of color and leaf designs can shine.', '2011-11-20 21:42:08.000000', NULL, 1),
(6599289, 983430, 23098, '<td valign="top">Sweet. Cute and cool with that ring tail.</td>', 'Sweet. Cute and cool with that ring tail.', '2011-11-20 21:42:16.000000', NULL, 1),
(6599290, 983634, 124815, '<td valign="top">The tourists take away some of the mysterious charm.</td>', 'The tourists take away some of the mysterious charm.', '2011-11-20 21:42:16.000000', NULL, 1),
