(6599297, 983759, 124815, '<td valign="top">Yes, no more, no less then The Dark Tower. Could be part of a serie of pics on the same subject.</td>', 'Yes, no more, no less then The Dark Tower. Could be part of a serie of pics on the same subject.', '2011-11-20 21:49:12.000000', NULL, 1),
(6599299, 983248, 124815, '<td valign="top">I have to love a picture independently of meeting the challenge and then for how it responds to it. Here, I appreciate the grain  but ... what do I do with the mum?</td>', 'I have to love a picture independently of meeting the challenge and then for how it responds to it. Here, I appreciate the grain  but ... what do I do with the mum?', '2011-11-20 21:52:04.000000', NULL, 1),
(6599301, 983662, 124815, '<td valign="top">Oh, I remember this olive tree. A beauty. Most photogenic.</td>', 'Oh, I remember this olive tree. A beauty. Most photogenic.', '2011-11-20 21:52:53.000000', NULL, 1),
(6599302, 983718, 124815, '<td valign="top">Nice silence here. I almost wish for more negative space.</td>', 'Nice silence here. I almost wish for more negative space.', '2011-11-20 21:53:44.000000', NULL, 1),
(6599303, 983140, 124815, '<td valign="top">What a spooky image! Bad things seem to happen and the only witness seems to be this cat. 9</td>', 'What a spooky image! Bad things seem to happen and the only witness seems to be this cat. 9', '2011-11-20 21:54:47.000000', NULL, 1),
(6599305, 983905, 124815, '<td valign="top">Seems as it''s the last remaining picture of a haunted house. Has its charm.</td>', 'Seems as it''s the last remaining picture of a haunted house. Has its charm.', '2011-11-20 21:56:19.000000', NULL, 1),
(6599306, 983897, 43774, '<td valign="top">Love that one leaf on the windowsill.</td>', 'Love that one leaf on the windowsill.', '2011-11-20 21:57:03.000000', NULL, 1),
(6599307, 982870, 124815, '<td valign="top">I think I need more of the forehead cropped to get more of the opressive feeling.</td>', 'I think I need more of the forehead cropped to get more of the opressive feeling.', '2011-11-20 21:57:49.000000', NULL, 1),
(6599308, 983497, 124815, '<td valign="top">A Bergman-esque flavor here. Good.</td>', 'A Bergman-esque flavor here. Good.', '2011-11-20 21:58:44.000000', NULL, 1),
(6599310, 982897, 124815, '<td valign="top">Too bad that this image is not bigger. But even so, it has the flavor of a wax museum figure.</td>', 'Too bad that this image is not bigger. But even so, it has the flavor of a wax museum figure.', '2011-11-20 22:00:17.000000', NULL, 1),
